import os
import sys
import tempfile
import warnings

import click


@click.group()
@click.option("-f", type=click.File("r"))
def cli(f):
    pass


@cli.command()
def sub():
    pass


@click.group(chain=True)
@click.option("-f", type=click.File("r"))
def cli_chain(f):
    pass


@cli_chain.command()
def sub2():
    pass


def run_case(name, command, argv, comp_words):
    fd, path = tempfile.mkstemp(suffix=".json")
    os.close(fd)
    os.environ.pop("_CLI_COMPLETE", None)
    env = {
        "_CLI_COMPLETE": "bash_complete",
        "COMP_WORDS": '"prog" ' + " ".join(f'"{a}"' for a in [*argv, ""]),
        "COMP_CWORD": str(len(argv) + 1),
    }
    old = {}
    try:
        for k, v in env.items():
            old[k] = os.environ.get(k)
            os.environ[k] = v
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter("always")
            try:
                command.main(standalone_mode=True, prog_name="prog")
            except SystemExit:
                pass
    finally:
        for k, v in old.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
        os.unlink(path)

    resource_warnings = [w for w in caught if issubclass(w.category, ResourceWarning)]
    print(f"--- {name}: {len(resource_warnings)} ResourceWarning(s)")
    for w in resource_warnings:
        print("   ", w.message)
    return len(resource_warnings)


# file option value on the group, completing a subcommand
n1 = run_case("group + file option, complete sub", cli, ["-f", "/tmp/x.json"], None)
n2 = run_case("chained group + file option, complete sub", cli_chain, ["-f", "/tmp/x.json", "sub2"], None)

sys.exit(1 if (n1 or n2) else 0)

