import gc
import os
import sys
import warnings

import click

FILE = "testdata_tmp.json"


@click.group()
@click.option("-f", type=click.File("r"))
def cli(f):
    pass


@cli.group()
@click.option("-g", type=click.File("r"))
def mid(g):
    pass


@mid.command()
@click.option("-s", type=click.File("r"))
def deep(s):
    pass


@cli.command()
@click.argument("path", type=click.File("r"))
def takefile(path):
    pass


@click.group(chain=True)
@click.option("-f", type=click.File("r"))
def cli_chain(f):
    pass


@cli_chain.command()
@click.option("-s", type=click.File("r"))
def sub2(s):
    pass


def run_case(name, command, argv, incomplete=""):
    env = {
        "_PROG_COMPLETE": "bash_complete",
        "COMP_WORDS": '"prog" ' + " ".join(f'"{a}"' for a in [*argv, incomplete]),
        "COMP_CWORD": str(len(argv) + 1),
    }
    old = {}
    n = 0
    try:
        for k, v in env.items():
            old[k] = os.environ.get(k)
            os.environ[k] = v
        with warnings.catch_warnings(record=True) as caught:
            warnings.simplefilter("always")
            try:
                command.main(standalone_mode=True, prog_name="prog")
            except SystemExit:
                pass
            gc.collect()
        resource_warnings = [
            w for w in caught if issubclass(w.category, ResourceWarning)
        ]
        n = len(resource_warnings)
    finally:
        for k, v in old.items():
            if v is None:
                os.environ.pop(k, None)
            else:
                os.environ[k] = v
    print(f"--- {name}: {n} ResourceWarning(s)")
    for w in caught:
        if issubclass(w.category, ResourceWarning):
            print("   ", w.message)
    return n


total = 0
total += run_case("group file opt, complete sub", cli, ["-f", FILE])
total += run_case("group file opt, complete mid sub", cli, ["-f", FILE, "mid"])
total += run_case("nested groups file opts, complete deep", cli, ["-f", FILE, "mid", "-g", FILE])
total += run_case("nested groups, complete deep option", cli, ["-f", FILE, "mid", "-g", FILE, "deep", "-s"])
total += run_case("command file arg, complete next", cli, ["-f", FILE, "takefile", FILE])
