total += run_case("chained group, complete after sub2", cli_chain, ["-f", FILE, "sub2", FILE])
total += run_case("no file args, complete sub", cli, [])
total += run_case("plain command completion", cli, ["-f", FILE], incomplete="-")

print("TOTAL:", total)
sys.exit(1 if total else 0)

